def gen(rng):
    def fmt(eqs, qs):
        return (str(len(eqs)) + '\n' + '\n'.join(f'{a} {b} {k}' for a, b, k in eqs)
                + '\n' + str(len(qs)) + '\n' + '\n'.join(f'{x} {y}' for x, y in qs))

    def small():
        nv = rng.randint(2, 8)
        names = rng.sample(['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'x1', 'y2'], nv)
        val = {u: rng.randint(1, 12) for u in names}
        eqs = []
        for _ in range(rng.randint(1, nv + 2)):
            u, v = rng.choice(names), rng.choice(names)
            if val[u] % val[v] == 0:
                eqs.append((u, v, val[u] // val[v]))
            elif val[v] % val[u] == 0:
                eqs.append((v, u, val[v] // val[u]))
        if not eqs:
            eqs.append((names[0], names[0], 1))
        pool = names + ['zz']
        qs = [(rng.choice(pool), rng.choice(pool)) for _ in range(rng.randint(1, 8))]
        return fmt(eqs, qs)

    def queries(names, nq):
        qs = []
        for _ in range(nq):
            x = rng.choice(names) if rng.random() > 0.01 else 'zz'
            y = rng.choice(names) if rng.random() > 0.01 else 'zz9'
            qs.append((x, y))
        return qs

    def tree_case(nv, parent_fn, kmax, nq):
        names = ['v%d' % i for i in range(nv)]
        rng.shuffle(names)
        eqs = []
        for i in range(1, nv):
            p = parent_fn(i)
            k = rng.randint(1, kmax)
            if rng.random() < 0.5:
                eqs.append((names[i], names[p], k))
            else:
                eqs.append((names[p], names[i], k))
        return fmt(eqs, queries(names, nq))

    tests = [
        fmt([('a', 'a', 1)], [('a', 'a'), ('b', 'b'), ('a', 'b')]),
        fmt([('a', 'b', 1000000), ('b', 'c', 1000000)], [('a', 'c'), ('c', 'a'), ('b', 'a')]),
        fmt([('x', 'y', 2), ('y', 'z', 2), ('x', 'z', 4)], [('x', 'z'), ('z', 'x'), ('y', 'y')]),
    ]
    for _ in range(40):
        tests.append(small())
    tests.append(tree_case(20001, lambda i: rng.randint(0, i - 1), 10**6, 20000))
    tests.append(tree_case(20001, lambda i: i - 1, 10**6, 20000))
    tests.append(tree_case(20001, lambda i: (i - 1) // 2, 10, 20000))

    nv = 3000
    names = ['v%d' % i for i in range(nv)]
    e = [rng.randint(0, 19) for _ in range(nv)]
    eqs = []
    for _ in range(20000):
        u, v = rng.randrange(nv), rng.randrange(nv)
        if e[u] < e[v]:
            u, v = v, u
        eqs.append((names[u], names[v], 2 ** (e[u] - e[v])))
    tests.append(fmt(eqs, queries(names, 20000)))

    names = ['v%d' % i for i in range(19600)]
    eqs = []
    for blk in range(400):
        base = blk * 49
        for j in range(1, 49):
            p = base + rng.randint(0, j - 1)
            k = rng.randint(1, 1000)
            eqs.append((names[base + j], names[p], k) if rng.random() < 0.5 else (names[p], names[base + j], k))
    rng.shuffle(eqs)
    tests.append(fmt(eqs, queries(names, 20000)))
    return tests

