    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int m = Integer.parseInt(st.nextToken());
        String[] a = new String[m], b = new String[m];
        long[] k = new long[m];
        for (int i = 0; i < m; i++) {
            a[i] = st.nextToken();
            b[i] = st.nextToken();
            k[i] = Long.parseLong(st.nextToken());
        }
        int q = Integer.parseInt(st.nextToken());
        String[][] queries = new String[q][2];
        for (int i = 0; i < q; i++) {
            queries[i][0] = st.nextToken();
            queries[i][1] = st.nextToken();
        }
        long[] res = answerQueries(a, b, k, queries);
        StringBuilder sb = new StringBuilder();
        for (long r : res) sb.append(r).append('\n');
        System.out.print(sb);
    }
}
